// Tous les chiffres sont calculés ici, par le code. L'IA ne fait que rédiger à partir de ce résultat.
const conf = $('Configuration').first().json;
const ref = new Date(conf.date_du_point + 'T00:00:00Z');
const J = 86400000;
const jours = (d) => Math.round((ref - new Date(d + 'T00:00:00Z')) / J);
const ETAPES = [['Candidature reçue','recue_le'],['Premier échange','premier_echange_le'],['Business case','business_case_le'],['Entretien métier','entretien_metier_le'],['Entretien inversé','entretien_inverse_le'],['Entretien final','entretien_final_le'],['Offre','offre_le'],['Embauche','embauche_le']];
const rows = $input.all().map((i) => i.json);
const enCours = rows.filter((r) => r.statut === 'En cours');
const embauches = rows.filter((r) => r.statut === 'Embauché');
const moy = (a) => (a.length ? Math.round((a.reduce((s, x) => s + x, 0) / a.length) * 10) / 10 : 0);
const ecart = (a, b) => (new Date(b) - new Date(a)) / J;

const entonnoir = ETAPES.map(([etape, c]) => ({ etape, nb: rows.filter((r) => r[c]).length }));
entonnoir.forEach((x, i) => { x.passage = i ? Math.round((100 * x.nb) / entonnoir[i - 1].nb) : null; });

const delais = ETAPES.slice(1).map(([etape, c], i) => {
  const avant = ETAPES[i][1];
  return { passage: ETAPES[i][0] + ' → ' + etape, jours: moy(rows.filter((r) => r[c]).map((r) => ecart(r[avant], r[c]))) };
});
const plusLent = delais.reduce((a, b) => (b.jours > a.jours ? b : a));

const compte = (c, a, b) => rows.filter((r) => r[c] && jours(r[c]) >= a && jours(r[c]) < b).length;
const semaine = { recues: compte('recue_le', 0, 7), recues_avant: compte('recue_le', 7, 14), premiers_echanges: compte('premier_echange_le', 0, 7), premiers_echanges_avant: compte('premier_echange_le', 7, 14), offres: compte('offre_le', 0, 7), embauches: compte('embauche_le', 0, 7) };

const parSource = {};
rows.forEach((r) => { const s = (parSource[r.source] ||= { source: r.source, candidatures: 0, retenus: 0, embauches: 0 }); s.candidatures++; if (r.premier_echange_le) s.retenus++; if (r.statut === 'Embauché') s.embauches++; });
const sources = Object.values(parSource).map((s) => ({ ...s, taux: Math.round((100 * s.retenus) / s.candidatures) })).sort((a, b) => b.taux - a.taux);

const charge = {};
enCours.forEach((r) => { charge[r.recruteur] = (charge[r.recruteur] || 0) + 1; });
const recruteurs = Object.entries(charge).map(([nom, nb]) => ({ nom, nb })).sort((a, b) => b.nb - a.nb);

const ACTION = { 'Candidature reçue': 'Trier la candidature et répondre au candidat', 'Premier échange': 'Proposer le business case ou clore avec un retour', 'Business case': 'Relancer pour le rendu ou fixer le débrief', 'Entretien métier': "Programmer l'entretien inversé", 'Entretien inversé': "Planifier l'entretien final", 'Entretien final': "Décider et préparer l'offre", 'Offre': "Relancer la réponse à l'offre" };
const derniere = (r) => ETAPES.map(([, c]) => r[c]).filter(Boolean).pop();
const relances = enCours.map((r) => ({ candidat: r.candidat, poste: r.poste, etape: r.etape_actuelle, recruteur: r.recruteur, jours: jours(derniere(r)), action: ACTION[r.etape_actuelle] || 'Faire le point' }))
  .filter((x) => x.jours > conf.seuil_relance_jours).sort((a, b) => b.jours - a.jours);

const delaiEmbauche = Math.round(moy(embauches.map((r) => ecart(r.recue_le, r.embauche_le))));
const resume = [
  'Point du ' + conf.date_du_point + '.',
  'Dans la table : ' + rows.length + ' candidatures, ' + enCours.length + ' en cours, ' + embauches.length + ' embauches, ' + delaiEmbauche + " jours en moyenne de la candidature à l'embauche.",
  'Cette semaine : ' + semaine.recues + " candidatures reçues (" + semaine.recues_avant + " la semaine d'avant), " + semaine.premiers_echanges + ' premiers échanges (' + semaine.premiers_echanges_avant + " la semaine d'avant), " + semaine.offres + ' offres, ' + semaine.embauches + ' embauches.',
  "Taux de passage d'une étape à l'autre : " + entonnoir.slice(1).map((x) => x.etape + ' ' + x.passage + ' %').join(', ') + '.',
  'Passage le plus lent : ' + plusLent.passage + ', ' + plusLent.jours + ' jours en moyenne.',
  'Sources (part des candidats retenus au premier échange) : ' + sources.map((s) => s.source + ' ' + s.taux + ' % sur ' + s.candidatures).join(' ; ') + '.',
  'Candidats en cours par recruteur : ' + recruteurs.map((x) => x.nom + ' ' + x.nb).join(', ') + '.',
  'Candidats en attente depuis plus de ' + conf.seuil_relance_jours + ' jours : ' + relances.length + (relances.length ? ' (' + relances.map((x) => x.candidat + ', ' + x.poste + ', ' + x.etape + ', ' + x.recruteur + ', ' + x.jours + ' j').join(' ; ') + ')' : '') + '.',
].join('\n');

return [{ json: { date_du_point: conf.date_du_point, total: rows.length, en_cours: enCours.length, embauches: embauches.length, delai_embauche: delaiEmbauche, semaine, entonnoir, delais, plus_lent: plusLent, sources, recruteurs, relances, resume } }];

const k = $('Calculer les indicateurs').first().json;
const conf = $('Configuration').first().json;
const texte = ($input.first().json.text || '').replace(/```html|```/g, '').trim();
const accent = '#2F5D8A', encre = '#222C36', doux = '#5B6570', ligne = '#EFE4D3';
const tuile = (v, l) => '<td style="padding:12px 14px;border:1px solid ' + ligne + ';border-radius:10px;text-align:center;width:25%"><div style="font:600 26px Georgia,serif;color:' + encre + '">' + v + '</div><div style="font-size:12px;color:' + doux + '">' + l + '</div></td>';
const evol = (a, b) => a + ' <span style="color:' + doux + '">(' + b + " la semaine d'avant)</span>";
const lignes = k.relances.map((r) => '<tr><td style="padding:6px 8px;border-bottom:1px solid ' + ligne + '">' + r.candidat + '</td><td style="padding:6px 8px;border-bottom:1px solid ' + ligne + '">' + r.poste + '</td><td style="padding:6px 8px;border-bottom:1px solid ' + ligne + '">' + r.etape + '</td><td style="padding:6px 8px;border-bottom:1px solid ' + ligne + '">' + r.recruteur + '</td><td style="padding:6px 8px;border-bottom:1px solid ' + ligne + ';text-align:right">' + r.jours + ' j</td></tr>').join('');
const html = '<div style="font-family:Helvetica,Arial,sans-serif;color:' + encre + ';max-width:640px;margin:0 auto">'
 + '<p style="font-size:12px;color:' + accent + ';font-weight:700;letter-spacing:.06em;text-transform:uppercase;margin:0">Recrutement</p>'
 + '<h1 style="font:600 28px Georgia,serif;margin:4px 0 16px">Point recrutement du lundi ' + k.date_du_point.split('-').reverse().join('/') + '</h1>'
 + '<table style="width:100%;border-collapse:separate;border-spacing:8px 0"><tr>' + tuile(k.total, 'candidatures') + tuile(k.en_cours, 'en cours') + tuile(k.embauches, 'embauches') + tuile(k.delai_embauche + ' j', "jusqu'à l'embauche") + '</tr></table>'
 + '<div style="font-size:15px;line-height:1.5;margin-top:12px">' + texte + '</div>'
 + '<h3 style="margin:18px 0 6px">Cette semaine</h3><ul style="font-size:14px;line-height:1.6;margin:0;padding-left:18px">'
 + '<li>Candidatures reçues : ' + evol(k.semaine.recues, k.semaine.recues_avant) + '</li>'
 + '<li>Premiers échanges : ' + evol(k.semaine.premiers_echanges, k.semaine.premiers_echanges_avant) + '</li>'
 + '<li>Offres : ' + k.semaine.offres + ', embauches : ' + k.semaine.embauches + '</li></ul>'
 + '<h3 style="margin:18px 0 6px">' + k.relances.length + ' relances créées dans Notion</h3>'
 + '<table style="width:100%;border-collapse:collapse;font-size:13px">' + lignes + '</table>'
 + '<p style="margin:16px 0"><a href="' + conf.lien_relances + '" style="display:inline-block;background:' + accent + ';color:#fff;text-decoration:none;font-weight:700;padding:10px 16px;border-radius:8px">Ouvrir les relances dans Notion</a></p>'
 + '<p style="font-size:12px;color:' + doux + '">Chiffres calculés par le code, texte rédigé par Claude.</p></div>';
return [{ json: { html, sujet: 'Point recrutement du lundi ' + k.date_du_point.split('-').reverse().join('/'), destinataire: conf.destinataire } }];

// Une seule tâche par candidat et par point : rien n'est créé deux fois
const deja = ($input.first().json.results || []).map((p) => ((p.properties.Candidat || {}).title || [])[0]?.plain_text);
const date = $('Configuration').first().json.date_du_point;
return $('Calculer les indicateurs').first().json.relances.filter((r) => !deja.includes(r.candidat)).map((r) => ({ json: { ...r, date } }));
